    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '121: "Preterm Labor" is defined as contractions and cervical change between:', '["20 0/7 and 36 6/7 weeks", "24 and 40 weeks", "10 and 20 weeks", "None"]', 0, 'Standard clinical definition. (ACOG)'),
    (v_topic_id, '122: Which test has a high "Negative Predictive Value" (99%) for predicting NO delivery within 7-14 days in patients with preterm contractions?', '["Cervical length", "Fetal Fibronectin (fFN)", "Nitrazine", "Ultrasound for weight"]', 1, 'If fFN is negative, the patient is very unlikely to deliver soon. (Williams)'),
    (v_topic_id, '123: What is the primary purpose of "Tocolytics" (e.g., Nifedipine, Indomethacin)?', '["To stop labor indefinitely", "To delay delivery for 48 hours to allow for steroid administration", "To prevent infection", "To increase birth weight"]', 1, 'Tocolysis is a "bridge" for steroids and transport. (ACOG)'),
    (v_topic_id, '124: "Magnesium Sulfate" in the setting of preterm birth < 32 weeks is given for:', '["Tocolysis", "Fetal Neuroprotection (reduces risk of Cerebral Palsy)", "Treating HTN", "Stopping bleeding"]', 1, 'Proven benefit for the neonate. (ACOG)'),
    (v_topic_id, '125: "Cervical Insufficiency" typically presents as:', '["Painful contractions and bleeding", "Painless cervical dilation in the 2nd trimester", "Fever", "Large baby"]', 1, 'Often leads to mid-trimester pregnancy loss. (Beckmann)'),
    (v_topic_id, '126: Treatment for Cervical Insufficiency?', '["Bed rest", "Cervical Cerclage (suture around the cervix)", "Steroids", "Induction"]', 1, 'Placed at 12-14 weeks in history-indicated cases. (Williams)'),
    (v_topic_id, '127: A "Short Cervix" found on ultrasound (< 25 mm) at 20 weeks in a woman with NO prior preterm birth is managed with:', '["Immediate Cerclage", "Vaginal Progesterone", "Bed rest", "C-section"]', 1, 'Progesterone reduces risk of PTB in asymptomatic short cervix. (ACOG)'),
    (v_topic_id, '128: "Preterm Premature Rupture of Membranes" (PPROM) management at 30 weeks?', '["Immediate delivery", "Expectant management, Latency Antibiotics, Steroids", "C-section", "Home monitoring"]', 1, 'Goal is to safely gain gestational age. (ACOG)'),
    (v_topic_id, '129: "Latency Antibiotics" for PPROM traditionally consist of:', '["Penicillin only", "Ampicillin + Erythromycin (followed by Amoxicillin + Erythromycin)", "Ceftriaxone", "Vancomycin"]', 1, 'Extends the "latency period" before labor begins. (Williams)'),
    (v_topic_id, '130: Which "Steroid" regimen is used for fetal lung maturity?', '["Prednisone", "Betamethasone (2 doses 24h apart) or Dexamethasone", "Hydrocortisone", "Estrogen"]', 1, 'Standard high-yield regimen. (ACOG)'),
    (v_topic_id, '131: "Fetal Fibronectin" test should NOT be performed if:', '["The patient is 30 weeks", "There has been intercourse, digital exam, or bleeding in the last 24h", "The patient has twins", "The patient is nulliparous"]', 1, 'These factors lead to false positive results. (Beckmann)'),
    (v_topic_id, '132: "Indomethacin" tocolysis is contraindicated after 32 weeks due to risk of:', '["Maternal renal failure", "Premature closure of the fetal Ductus Arteriosus", "Heart defects", "Limb defects"]', 1, 'Also causes oligohydramnios. (Williams)'),
    (v_topic_id, '133: A patient at 28 weeks has PPROM and develops fever, maternal tachycardia, and uterine tenderness. Management?', '["Wait for steroids to finish", "Immediate delivery and broad-spectrum antibiotics (Endometritis/Chorioamnionitis)", "Tocolytics", "Bed rest"]', 1, 'Infection is a mandate for delivery regardless of gestational age. (ACOG)'),
    (v_topic_id, '134: In Rh-alloimmunization, what is the significance of the "Liley Curve"?', '["Measures fetal weight", "Spectrophotometric analysis of amniotic fluid bilirubin (delta OD450)", "Measures heart rate", "Checks for GDM"]', 1, 'Predicts severity of fetal hemolysis (Zones 1, 2, 3). (Williams)'),
    (v_topic_id, '135: "Intrauterine Fetal Transfusion" (IUT) is indicated if the fetus has:', '["Severe anemia (Hct < 30% or Zone 3 Liley)", "Normal Dopplers", "Large size", "Twins"]', 0, 'Blood is transfused into the umbilical vein. (ACOG)'),
    (v_topic_id, '136: Which "Ig" class of antibodies causes HDFN?', '["IgM (does not cross placenta)", "IgG (crosses placenta)", "IgA", "IgE"]', 1, 'IgM is too large; IgG is the culprit. (Beckmann)'),
    (v_topic_id, '137: "Kell" alloimmunization is particularly dangerous because Anti-Kell antibodies:', '["Are very small", "Suppress fetal erythropoiesis in addition to causing hemolysis", "Only affect the mother", "Cause diabetes"]', 1, 'Fetal anemia occurs faster and is more severe than in Rh disease. (Williams)'),
    (v_topic_id, '138: "Maternal-Fetal Hemorrhage" (MFH) can be triggered by:', '["Abdominal trauma", "Amniocentesis", "Placental abruption", "All of the above"]', 3, 'Requires KB test and extra RhoGAM if Rh-negative. (ACOG)'),
    (v_topic_id, '139: "Oligohydramnios" (AFI < 5 cm) is associated with:', '["Potter Sequence (pulmonary hypoplasia, limb deformities, flattened facies)", "Macrosomia", "Excessive swallowing", "Large placenta"]', 0, 'Due to lack of cushioning and fetal lung expansion. (Williams)'),
    (v_topic_id, '140: "Polyhydramnios" (AFI > 24 cm) is associated with:', '["Anencephaly and Esophageal atresia", "Renal agenesis", "HTN", "IUGR"]', 0, 'Anything that prevents fetal swallowing or increases urine. (Beckmann)'),
    (v_topic_id, '141: What is the most common fetal heart anomaly in babies of "Pre-gestational" diabetics?', '["Tetralogy of Fallot", "Transposition of the Great Arteries and VSD", "Patent Ductus Arteriosus", "None"]', 1, 'Cardiac defects are the most common malformations. (Williams)'),
    (v_topic_id, '142: "Caudal Regression Syndrome" (sacral agenesis) is pathognomonic for:', '["Chromosomal issues", "Maternal diabetes (pre-gestational)", "Infection", "Smoking"]', 1, 'Rare but highly specific. (Beckmann)'),
    (v_topic_id, '143: Neonatal "Hypoglycemia" in infants of diabetic mothers is caused by:', '["Low maternal sugar", "Hyperinsulinemia in the neonate (stimulated by maternal hyperglycemia in utero)", "Poor feeding", "Liver failure"]', 1, 'The baby''s pancreas is "revved up" and keeps producing insulin after birth. (Williams)'),
    (v_topic_id, '144: "Macrosomia" is defined by ACOG as birth weight > _____ grams in a diabetic mother.', '["4000", "4500", "5000", "3500"]', 1, 'Higher risk of shoulder dystocia. (ACOG)'),
    (v_topic_id, '145: "Shoulder Dystocia" is more common in diabetic pregnancies because:', '["The head is larger", "The baby has increased fat deposition on the shoulders and trunk (asymmetric growth)", "The mother''s pelvis is smaller", "Labor is faster"]', 1, 'The "fat" shoulders get stuck behind the symphysis. (Beckmann)'),
    (v_topic_id, '146: Maternal "Heart Disease" is classified using which system?', '["TNM", "NYHA (New York Heart Association) Classes I-IV", "Bishop", "Apgar"]', 1, 'Based on functional capacity and symptoms. (Williams)'),
    (v_topic_id, '147: Which cardiac condition has the highest maternal mortality risk (up to 50%)?', '["Mitral valve prolapse", "Eisenmenger Syndrome (Pulmonary HTN)", "Mild Aortic Stenosis", "Atrial Septal Defect"]', 1, 'Pregnancy is strongly discouraged in these patients. (ACOG)'),
    (v_topic_id, '148: "Peripartum Cardiomyopathy" recurrence risk in subsequent pregnancy?', '["0%", "Very high, especially if EF did not fully recover", "5%", "100%"]', 1, 'Mother should be counseled against future pregnancy if EF < 50-55%. (Williams)'),
    (v_topic_id, '149: "Deep Vein Thrombosis" (DVT) in pregnancy most commonly occurs in which leg?', '["Right", "Left (L-MAY syndrome)", "Both equally", "Arms only"]', 1, 'The right iliac artery compresses the left iliac vein. (Beckmann)'),
    (v_topic_id, '150: "Pulmonary Embolism" (PE) is diagnosed in pregnancy by:', '["D-dimer (often elevated normally in pregnancy)", "V/Q Scan or CTPA (CT Pulmonary Angiogram)", "Chest X-ray only", "Clinical guess"]', 1, 'Imaging is necessary and safe. (ACOG)'),
    (v_topic_id, '151: "Sickle Cell Disease" in pregnancy increases risk of:', '["Vaso-occlusive crises", "Pre-eclampsia", "IUGR", "All of the above"]', 3, 'Requires frequent monitoring and hydration. (Williams)'),
    (v_topic_id, '152: "Parvovirus B19" infection in a woman with Sickle Cell can cause:', '["Hydrops", "Aplastic Crisis", "Diabetes", "Blindness"]', 1, 'Virus shuts down RBC production. (Beckmann)'),
    (v_topic_id, '153: "Acute Cholecystitis" in pregnancy is more common due to:', '["Estrogen (increases cholesterol saturation) and Progesterone (slows gallbladder emptying)", "Eating more", "Dehydration", "Exercise"]', 0, 'A classic physiological predisposition. (Williams)'),
    (v_topic_id, '154: "Thyroid Storm" symptoms?', '["Hyperthermia, Tachycardia, Altered Mental Status, and GI symptoms", "Weight gain", "Hypotension", "Cold intolerance"]', 0, 'Life-threatening emergency. (Williams)'),
    (v_topic_id, '155: "Epilepsy" management in pregnancy?', '["Stop all meds", "Use the lowest effective dose of a single agent (monotherapy) and high-dose Folic Acid", "Switch to Valproate", "None"]', 1, 'Folic acid (4mg) helps prevent NTDs associated with AEDs. (ACOG)'),
    (v_topic_id, '156: "Valproic Acid" (Depakote) is generally avoided in pregnancy because of high risk for:', '["Limb defects", "Neural Tube Defects (Spina bifida)", "Blindness", "Deafness"]', 1, 'Most teratogenic of the common AEDs. (Williams)'),
    (v_topic_id, '157: "Thrombocytopenia" of pregnancy (Gestational Thrombocytopenia) is:', '["Dangerous", "Benign, mild (> 70-100k), and occurs in the 3rd trimester", "Always requires treatment", "Genetic"]', 1, 'Does not affect the neonate and resolves postpartum. (ACOG)'),
    (v_topic_id, '158: "Intrapartum" management of a woman with "ITP" (Immune Thrombocytopenia)?', '["Avoid operative delivery and fetal scalp electrodes if possible", "C-section for everyone", "Platelet transfusion for everyone", "None"]', 0, 'Maternal antibodies can cross and cause fetal thrombocytopenia. (Beckmann)'),
    (v_topic_id, '159: "Cystic Fibrosis" patients in pregnancy:', '["Are usually fine", "Risk of malnutrition and respiratory failure as the uterus grows", "Always have twins", "None"]', 1, 'Require close nutritional and pulmonary monitoring. (Williams)'),
    (v_topic_id, '160: "Pruritus" without a rash in the 3rd trimester should always prompt a check for:', '["Bile acids (ICP)", "Glucose", "HbA1c", "BP"]', 0, 'To rule out Intrahepatic Cholestasis. (ACOG)'),
    (v_topic_id, '161: Maternal "Obesity" (BMI > 30) increases risk of:', '["Pre-eclampsia", "GDM", "Cesarean delivery and Wound infection", "All of the above"]', 3, 'One of the most common high-risk factors. (ACOG)'),
    (v_topic_id, '162: Recommended weight gain for an "Obese" patient (BMI > 30)?', '["25-35 lbs", "11-20 lbs", "50 lbs", "None"]', 1, 'Less than for normal weight patients. (IOM)'),
    (v_topic_id, '163: "Chronic Renal Disease" in pregnancy is most accurately monitored by:', '["BUN", "Serum Creatinine and 24-hour urine protein", "Urine dipstick", "BP only"]', 1, 'Creatinine > 1.4-1.5 is associated with higher complication rates. (Williams)'),
    (v_topic_id, '164: "Transplant" patients (e.g., Kidney) can have successful pregnancies if:', '["They are 2 years post-transplant with stable function", "They stop all meds", "They are 1 month post-transplant", "Never"]', 0, 'Immunosuppression must be maintained. (ACOG)'),
    (v_topic_id, '165: Which immunosuppressant is CONTRAINDICATED in pregnancy?', '["Cyclosporine", "Azathioprine", "Mycophenolate Mofetil (CellCept)", "Tacrolimus"]', 2, 'Highly teratogenic (ear/cleft/heart defects). (Williams)'),
    (v_topic_id, '166: "Inflammatory Bowel Disease" (UC/Crohn''s) in pregnancy?', '["Usually flares", "Best outcome if in remission at time of conception", "Requires C-section for everyone", "Meds are stopped"]', 1, 'Most IBD meds (except methotrexate) are safe. (ACOG)'),
    (v_topic_id, '167: "Multiple Sclerosis" (MS) in pregnancy typically:', '["Worsens", "Improves or stays stable (flares often occur postpartum)", "Leads to blindness", "None"]', 1, 'Pregnancy is a naturally immunosuppressed state. (Beckmann)'),
    (v_topic_id, '168: "Substance Use" screening in pregnancy?', '["Only for high-risk patients", "Universal screening using validated tools", "Not recommended", "Police only"]', 1, 'Early identification is key for intervention. (ACOG)'),
    (v_topic_id, '169: "Fetal Alcohol Syndrome" (FAS) characteristics?', '["Smooth philtrum, thin upper lip, and short palpebral fissures", "Large ears", "High birth weight", "Club foot"]', 0, 'Leading cause of preventable intellectual disability. (Williams)'),
    (v_topic_id, '170: "Neonatal Abstinence Syndrome" (NAS) is associated with maternal use of:', '["Cocaine", "Opioids (Heroin, Methadone, Buprenorphine)", "Alcohol", "Cigarettes"]', 1, 'Baby experience withdrawal after birth. (AAP)'),
    (v_topic_id, '171: "Smoking" in pregnancy is the leading cause of:', '["Pre-eclampsia", "Low Birth Weight / IUGR", "Diabetes", "Twins"]', 1, 'Carbon monoxide and nicotine cause placental vasoconstriction. (ACOG)'),
    (v_topic_id, '172: "Abruption" risk is increased in smokers.', '["True", "False", "Only in the 1st trimester", "Only if they have GDM"]', 0, 'Chronic placental damage. (Williams)'),
    (v_topic_id, '173: "Advanced Maternal Age" (AMA) is defined as age > _____ at EDD.', '["30", "35", "40", "45"]', 1, 'Increases risk of aneuploidy and medical complications. (ACOG)'),
    (v_topic_id, '174: "Vanishing Twin" syndrome is:', '["Twins born at different times", "Death of one twin in the 1st trimester, often reabsorbed", "Missing twin at birth", "None"]', 1, 'Common with IVF. (Beckmann)'),
    (v_topic_id, '175: "Cervical Length" measurement via TVUS is most useful between which weeks for PTB screening?', '["12-16", "16-24", "24-32", "32-36"]', 1, 'Threshold for "short" is usually 20-25 mm. (ACOG)'),
    (v_topic_id, '176: A woman with a "prior spontaneous preterm birth" should receive which treatment starting at 16 weeks to prevent recurrence?', '["Bed rest", "Weekly 17-alpha-hydroxyprogesterone caproate (17-OHP) injections (though efficacy is currently under debate/FDA review)", "Aspirin", "Insulin"]', 1, 'The PROLONG trial questioned its efficacy, but it was standard for years. (ACOG)'),
    (v_topic_id, '177: "Emergency Cerclage" (Rescue Cerclage) is done for:', '["Short cervix on US", "Cervical dilation (e.g., 2 cm) in the 2nd trimester without contractions", "History only", "Twins"]', 1, 'Can help prolong pregnancy to viability. (Williams)'),
    (v_topic_id, '178: "Cordocentesis" (Percutaneous Umbilical Blood Sampling - PUBS) is used to:', '["Check for labor", "Access fetal blood for sampling or transfusion", "Check for previa", "Drain fluid"]', 1, 'Higher risk than amniocentesis. (Beckmann)'),
    (v_topic_id, '179: "Amniocentesis" for fetal lung maturity (L/S ratio) is now:', '["Standard for everyone", "Rarely used due to better dating and steroids", "Mandatory", "Dangerous"]', 1, 'L/S ratio > 2.0 indicates mature lungs. (Williams)'),
    (v_topic_id, '180: "Phosphatidylglycerol" (PG) in amniotic fluid is a marker of:', '["Infection", "Fetal lung maturity", "Diabetes", "Liver disease"]', 1, 'Present when lungs are mature. (Beckmann)');
